// UYAP form templates: merge the <data> payload into the document.
//
// Documents generated by UYAP (takip talebi, etc.) can arrive *unmerged*: the
// CDATA holds placeholder field names ("alacakliAdiSoyadi", "eol", "auto"…) and
// the real values sit in a <data> element after <styles>. The UYAP editor
// merges the two on display; this module does the same, producing an ordinary
// content.xml in the shape UYAP itself writes for merged documents (field runs
// keep their attributes and carry the value text, no <data>).
//
// Binding rules (verified against a real UYAP takip talebi):
//   - Element names in <data> encode digits as X+letter: Tablo40 → TabloXeXa.
//   - <paragraph GroupName=G>: shown only if G exists in the current data scope;
//     its runs then resolve inside G.
//   - Any run with fieldGroupName=G (field or literal text): shown only if G
//     exists in scope; a field's value is looked up inside G first.
//   - <field fieldName=N>: replaced by the text of data element N (nearest scope
//     first); missing/empty → dropped. "eol" is a line break, "ceol" a break
//     only when its value is "true"; values containing "\n" break lines too.
//   - <row rowType="dataRow" rowName=R> in <table tableName=T>: repeated once
//     per <R> child of data element <T>, each copy scoped to its instance;
//     no instances → row removed (and an emptied table removed).
import { DOMParser, XMLSerializer } from '@xmldom/xmldom';

const elems = (n) => {
  const out = [];
  for (let c = n?.firstChild; c; c = c.nextSibling) if (c.nodeType === 1) out.push(c);
  return out;
};
const encodeName = (name) => name.replace(/\d/g, (d) => `X${'abcdefghij'[d]}`);

/** First element named `name` (encoded or raw) under the innermost scope that has one (BFS). */
function findIn(scope, name) {
  if (!name) return null;
  const enc = encodeName(name);
  for (const s of scope) {
    const queue = elems(s);
    while (queue.length) {
      const e = queue.shift();
      if (e.tagName === enc || e.tagName === name) return e;
      queue.push(...elems(e));
    }
  }
  return null;
}

/** True when content.xml carries an unmerged UYAP data payload. */
export function hasTemplateData(xmlString) {
  return /<data[\s>]/.test(xmlString) && /<field\b/.test(xmlString);
}

/**
 * mergeTemplateData(xmlString) → { xml, merged }
 * Returns the input unchanged (merged: false) when there is nothing to merge.
 */
export function mergeTemplateData(xmlString) {
  if (!hasTemplateData(xmlString)) return { xml: xmlString, merged: false };
  const dom = new DOMParser({ onError: () => {} }).parseFromString(xmlString, 'text/xml');
  const root = dom.documentElement;
  if (!root || root.tagName !== 'template') return { xml: xmlString, merged: false };
  const kids = elems(root);
  const contentEl = kids.find((k) => k.tagName === 'content');
  const elementsEl = kids.find((k) => k.tagName === 'elements');
  const dataEl = kids.find((k) => k.tagName === 'data');
  if (!contentEl || !elementsEl || !dataEl) return { xml: xmlString, merged: false };

  const text = contentEl.textContent ?? '';
  const TXT = new WeakMap(); // run element → its text in the merged document
  const runText = (r) => text.substr(parseInt(r.getAttribute('startOffset') || '0', 10), parseInt(r.getAttribute('length') || '0', 10));

  const walk = (container, scope) => {
    for (const el of elems(container)) {
      if (el.tagName === 'paragraph') mergeParagraph(el, scope);
      else if (el.tagName === 'table') mergeTable(el, scope);
      else walk(el, scope);
    }
  };

  const mergeTable = (tEl, scope) => {
    const rows = elems(tEl);
    const tData = rows.some((r) => r.getAttribute('rowType') === 'dataRow') ? findIn(scope, tEl.getAttribute('tableName')) : null;
    for (const row of rows) {
      if (row.getAttribute('rowType') !== 'dataRow') { walk(row, scope); continue; }
      const rName = row.getAttribute('rowName');
      const instances = tData ? elems(tData).filter((e) => (rName ? e.tagName === encodeName(rName) || e.tagName === rName : /^row/.test(e.tagName))) : [];
      for (const inst of instances) {
        const copy = row.cloneNode(true);
        tEl.insertBefore(copy, row);
        walk(copy, [inst, ...scope]);
      }
      tEl.removeChild(row);
    }
    if (!elems(tEl).length) tEl.parentNode.removeChild(tEl);
  };

  const mergeParagraph = (pEl, scope) => {
    const parent = pEl.parentNode;
    const group = pEl.getAttribute('GroupName');
    if (group) {
      const g = findIn(scope, group);
      if (!g) { parent.removeChild(pEl); return; }
      scope = [g, ...scope];
    }
    const runs = elems(pEl);
    const lines = [[]];
    const cur = () => lines[lines.length - 1];
    const lineBreak = () => { if (cur().some((r) => TXT.get(r).trim())) lines.push([]); };
    const emit = (r, t) => {
      const parts = t.split(/\r?\n/);
      parts.forEach((p, i) => {
        if (i) lineBreak();
        if (!p) return;
        const c = r.cloneNode(false);
        TXT.set(c, p);
        cur().push(c);
      });
    };
    for (const r of runs) {
      pEl.removeChild(r);
      let rScope = scope;
      const fg = r.getAttribute('fieldGroupName');
      if (fg) {
        const g = findIn(scope, fg);
        if (!g) continue;
        rScope = [g, ...scope];
      }
      if (r.tagName !== 'field') {
        if (r.tagName === 'image') { TXT.set(r, '¸'); cur().push(r); } else emit(r, runText(r).replace(/[\r\n]/g, ''));
        continue;
      }
      const name = r.getAttribute('fieldName');
      if (name === 'eol') { lineBreak(); continue; }
      const v = findIn(rScope, name);
      const value = v ? v.textContent : '';
      if (name === 'ceol') { if (value.trim() === 'true') lineBreak(); continue; }
      if (value) emit(r, value);
    }
    // One <paragraph> per line; each ends with "\n" (UDF invariant).
    const first = runs.find((r) => r.tagName !== 'image');
    let prev = null;
    lines.forEach((line, i) => {
      const p = i ? pEl.cloneNode(false) : pEl;
      if (i) parent.insertBefore(p, prev.nextSibling);
      prev = p;
      const last = line[line.length - 1];
      if (last && last.tagName !== 'image') TXT.set(last, `${TXT.get(last)}\n`);
      else {
        const nl = dom.createElement('content');
        for (const k of ['family', 'size', 'bold', 'italic']) if (first?.getAttribute(k)) nl.setAttribute(k, first.getAttribute(k));
        TXT.set(nl, '\n');
        line.push(nl);
      }
      for (const r of line) p.appendChild(r);
    });
  };

  walk(elementsEl, [dataEl]);
  root.removeChild(dataEl);

  // Rebuild the CDATA in document order and renumber offsets.
  let out = '';
  const number = (n) => {
    for (const e of elems(n)) {
      if (TXT.has(e)) {
        const t = TXT.get(e);
        e.setAttribute('startOffset', String(out.length));
        e.setAttribute('length', String(t.length));
        out += t;
      } else number(e);
    }
  };
  number(elementsEl);
  while (contentEl.firstChild) contentEl.removeChild(contentEl.firstChild);
  contentEl.appendChild(dom.createCDATASection(out.replace(/]]>/g, ']] >')));
  return { xml: new XMLSerializer().serializeToString(dom), merged: true };
}
